//! Internal slot representations and containers for schematic blueprints.
//!
//! # Warning
//! This module contains **internal plumbing** types used by code generated by `#[schematic]`.
//! Application code and end users should not interact with [`Slot`], [`SingleSlot`], or [`MultiSlot`] directly.
//! Use macro-generated builders, [`SingleChoice`],
//! [`MultiChoice`], and the [`Schematic`] trait instead.

use crate::choice::{MultiChoice, SingleChoice};
use crate::error::SchematicError;
#[cfg(doc)]
use crate::schematic_trait::Schematic;
use serde::{Deserialize, Serialize};

/// Internal plumbing: generic container representing a slot in an unresolved schematic.
///
/// Holds either a choice `C`, an unresolved value `U`, or a pre-resolved value `R`.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum Slot<U, R, C> {
    /// Slot contains a choice `C` waiting to be resolved.
    Choose(C),
    /// Slot contains a fixed, unresolved value `U`.
    FixedUnresolved(U),
    /// Slot contains a fixed, resolved value `R`.
    FixedResolved(R),
}

/// Internal plumbing: slot specialization for [`SingleChoice`].
pub type SingleSlot<U, R> = Slot<U, R, SingleChoice<U>>;

/// Internal plumbing: slot specialization for [`MultiChoice`].
///
/// Holds either a [`MultiChoice<U>`] choice or a fixed collection (`Vec<U>` / `Vec<R>`).
pub type MultiSlot<U, R> = Slot<Vec<U>, Vec<R>, MultiChoice<U>>;

impl<U, R, C> Slot<U, R, C> {
    /// Returns a reference to the inner choice if this slot is a [`Slot::Choose`].
    pub fn as_choice(&self) -> Option<&C> {
        match self {
            Slot::Choose(c) => Some(c),
            _ => None,
        }
    }

    /// Returns a mutable reference to the inner choice if this slot is a [`Slot::Choose`].
    pub fn as_choice_mut(&mut self) -> Option<&mut C> {
        match self {
            Slot::Choose(c) => Some(c),
            _ => None,
        }
    }

    /// Returns a reference to the inner unresolved value if this slot is a [`Slot::FixedUnresolved`].
    pub fn as_unresolved(&self) -> Option<&U> {
        match self {
            Slot::FixedUnresolved(u) => Some(u),
            _ => None,
        }
    }

    /// Returns a reference to the inner resolved value if this slot is a [`Slot::FixedResolved`].
    pub fn as_resolved(&self) -> Option<&R> {
        match self {
            Slot::FixedResolved(r) => Some(r),
            _ => None,
        }
    }
}

impl<U, R> From<SingleChoice<U>> for SingleSlot<U, R> {
    fn from(choice: SingleChoice<U>) -> Self {
        Slot::Choose(choice)
    }
}

impl<U, R> From<MultiChoice<U>> for MultiSlot<U, R> {
    fn from(choice: MultiChoice<U>) -> Self {
        Slot::Choose(choice)
    }
}

impl<U, R> From<U> for SingleSlot<U, R> {
    fn from(value: U) -> Self {
        Slot::FixedUnresolved(value)
    }
}

impl<U, R> From<Vec<U>> for MultiSlot<U, R> {
    fn from(value: Vec<U>) -> Self {
        Slot::FixedUnresolved(value)
    }
}

impl<U, R> SingleSlot<U, R> {
    /// Returns `true` if this slot contains an unconfirmed choice.
    pub fn is_pending(&self) -> bool {
        match self {
            Slot::Choose(c) => !c.is_made(),
            _ => false,
        }
    }

    /// Returns `true` if this slot contains a confirmed choice.
    pub fn is_made(&self) -> bool {
        match self {
            Slot::Choose(c) => c.is_made(),
            _ => false,
        }
    }

    /// Returns `true` if this slot is complete (fixed value or confirmed choice).
    pub fn is_complete(&self) -> bool {
        match self {
            Slot::FixedUnresolved(_) | Slot::FixedResolved(_) => true,
            Slot::Choose(c) => c.is_made(),
        }
    }
}

impl<T> SingleSlot<T, T> {
    /// Resolves the single slot into its concrete value.
    ///
    /// For non-cascading slots where $U = R$, pre-resolved values stored in
    /// [`Slot::FixedResolved`] are returned directly as `Ok(val)`.
    ///
    /// # Errors
    /// Returns [`SchematicError::UnresolvedChoice`] if the slot contains an unconfirmed choice.
    pub fn resolve_exact(self) -> Result<T, SchematicError> {
        match self {
            Slot::FixedUnresolved(u) => Ok(u),
            Slot::FixedResolved(r) => Ok(r),
            Slot::Choose(c) => c.resolve_exact(),
        }
    }
}

impl<U, R> MultiSlot<U, R> {
    /// Returns `true` if this slot contains an unconfirmed choice.
    pub fn is_pending(&self) -> bool {
        match self {
            Slot::Choose(c) => !c.is_made(),
            _ => false,
        }
    }

    /// Returns `true` if this slot contains a confirmed choice.
    pub fn is_made(&self) -> bool {
        match self {
            Slot::Choose(c) => c.is_made(),
            _ => false,
        }
    }

    /// Returns `true` if this slot is complete (fixed collection or confirmed choice).
    pub fn is_complete(&self) -> bool {
        match self {
            Slot::FixedUnresolved(_) | Slot::FixedResolved(_) => true,
            Slot::Choose(c) => c.is_made(),
        }
    }
}

impl<T> MultiSlot<T, T> {
    /// Resolves the multi-slot into a collection of concrete values without synthetic wrapping.
    ///
    /// For non-cascading pick slots ($U = R$), pre-resolved values stored in
    /// [`Slot::FixedResolved`] are returned directly as `Ok(val)`.
    ///
    /// # Errors
    /// Returns [`SchematicError::UnresolvedChoice`] if the slot contains an unconfirmed choice.
    pub fn resolve(self) -> Result<Vec<T>, SchematicError> {
        match self {
            Slot::FixedUnresolved(u) => Ok(u),
            Slot::FixedResolved(r) => Ok(r),
            Slot::Choose(c) => c.resolve(),
        }
    }
}
